import json
from collections import Counter
data = [0, 1, 2, 0, 1, 2, 0, 1, 0]
table = Counter()
for a, b, c in zip(data, data[1:], data[2:]):
    table[(a, b, c)] += 1
def next_symbol(a, b):
    return max(range(3), key=lambda c: (table[(a, b, c)], -c))
print(json.dumps({"after_0_1": next_symbol(0, 1), "count_0_1_2": table[(0, 1, 2)], "entries": len(table)},
                 sort_keys=True))
